			const bool lower_horizontal_pair = horizontal_pair_gate_4bc674(scratch_words, terrain_codes, width, height, level_tile_count, level, x, y + 1, terrain_id);
			choose_upper = !upper_horizontal_pair || lower_horizontal_pair;
