int32_t map_width_for_size_class(const std::string &size_class) {
	if (size_class == "homm3_xlarge" || size_class == "xlarge") {
		return 144;
	}
	if (size_class == "homm3_large" || size_class == "large") {
		return 108;
	}
	if (size_class == "homm3_medium" || size_class == "medium") {
		return 72;
	}
	if (size_class == "homm3_small" || size_class == "small") {
		return 36;
	}
	return 0;
}

int32_t water_mode_code(const std::string &water_mode) {
	if (water_mode == "normal_water") {
		return 1;
	}
	if (water_mode == "islands") {
		return 2;
	}
	return 0;
}

int32_t size_score(int32_t width, int32_t height, int32_t level_count, int32_t water_code) {
	int32_t score = int32_t((int64_t(std::max(1, width)) * int64_t(std::max(1, height)) * int64_t(std::max(1, level_count))) / 0x510);
	if (water_code == 2) {
		score = std::max(1, score / 2);
	}
	return score;
}

bool supports_one_level_land_scope(int32_t width, int32_t height, int32_t level_count, const std::string &water_mode, const std::string &size_class) {
	if (level_count != 1 || water_mode != "land" || width != height) {
		return false;
	}
	const int32_t expected_width = map_width_for_size_class(size_class);
	return expected_width > 0 && width == expected_width;
}

bool supports_recovered_workflow_execution_scope(
		int32_t width,
		int32_t height,
		int32_t level_count,
		const std::string &water_mode,
		const std::string &size_class) {
	if ((level_count != 1 && level_count != 2)
			|| (water_mode != "land" && water_mode != "normal_water" && water_mode != "islands")
			|| width != height) {
		return false;
	}
	const int32_t expected_width = map_width_for_size_class(size_class);
	if (expected_width <= 0 || width != expected_width) {
		return false;
	}
	if (level_count == 2) {
		return expected_width == 36
				|| expected_width == 72
				|| expected_width == 108
				|| expected_width == 144;
	}
	return true;
}

static bool supports_cli_recovery_probe_scope(const H3MapedRmgWorkflowConfig &config) {
	if (!config.recovery_probe_scope_allowed
			|| (config.level_count != 1 && config.level_count != 2)
			|| (config.water_mode != "land"
					&& config.water_mode != "normal_water"
					&& config.water_mode != "islands")
			|| config.width != config.height) {
		return false;
	}
	const int32_t expected_width = map_width_for_size_class(config.size_class);
	return expected_width > 0 && config.width == expected_width;
}

static bool supports_authority_backed_xlarge_normal_water_scope(
		const H3MapedRmgWorkflowConfig &config) {
	if (!config.same_run_payload_authority_profile_known
			|| config.size_class != "xlarge"
			|| config.water_mode != "normal_water"
			|| config.width != 144
			|| config.height != 144
			|| config.level_count != 1
			|| config.human_count != 1
			|| config.player_count != 2) {
		return false;
	}
	const std::string prefix =
			"H3MapEd XLarge one-level normal-water seed " + std::to_string(config.seed)
			+ ", human/computer down 1, computer-only down 1, monster strength ";
	if (config.same_run_payload_authority_profile.rfind(prefix, 0) != 0) {
		return false;
	}
	const std::string strength = config.same_run_payload_authority_profile.substr(prefix.size());
	return strength == "random"
			|| strength == "weak"
			|| strength == "normal"
			|| strength == "strong";
}

