static bool same_run_two_level_payload_profile_matches_config(
		const H3MapedRmgWorkflowConfig &config) {
	if (!config.same_run_payload_authority_profile_known
			|| config.level_count != 2
			|| config.human_count != 1
			|| config.player_count != 2) {
		return false;
	}
	std::string size_label;
	if (config.size_class == "small") {
		size_label = "Small";
	} else if (config.size_class == "medium") {
		size_label = "Medium";
	} else if (config.size_class == "large") {
		size_label = "Large";
	} else if (config.size_class == "xlarge") {
		size_label = "XLarge";
	} else {
		return false;
	}
	std::string water_label;
	if (config.water_mode == "land") {
		water_label = "no-water";
	} else if (config.water_mode == "normal_water") {
		water_label = "normal-water";
	} else if (config.water_mode == "islands") {
		water_label = "islands";
	} else {
		return false;
	}
	const std::string prefix =
			"H3MapEd " + size_label + " two-level " + water_label + " seed "
			+ std::to_string(config.seed)
			+ ", human/computer down 1, computer-only down 1, monster strength ";
	if (config.same_run_payload_authority_profile.rfind(prefix, 0) != 0) {
		return false;
	}
	const std::string strength = config.same_run_payload_authority_profile.substr(prefix.size());
	return strength == "random"
					|| strength == "weak"
					|| strength == "normal"
					|| strength == "strong";
}

static bool supports_workflow_execution_scope(const H3MapedRmgWorkflowConfig &config) {
	return supports_recovered_workflow_execution_scope(
				config.width,
				config.height,
				config.level_count,
				config.water_mode,
				config.size_class)
			|| supports_cli_recovery_probe_scope(config)
			|| supports_authority_backed_xlarge_normal_water_scope(config)
			|| supports_authority_backed_large_islands_scope(config)
			|| supports_authority_backed_xlarge_islands_scope(config)
			|| same_run_two_level_payload_profile_matches_config(config);
}

