static bool final_header_assign_team_group_0x4ad140(
		int32_t team_count,
		int32_t player_count,
		int32_t first_team,
		const std::array<uint8_t, 8> &group_members,
		std::array<uint8_t, 8> &assignments,
		H3MapedRng &rng) {
	if (team_count <= 0 || player_count <= 0 || team_count > player_count) {
		return player_count == 0 && team_count == 0;
	}
	std::array<int32_t, 8> remaining {};
	const int32_t remainder = player_count % team_count;
	for (int32_t team = 0; team < team_count; ++team) {
		remaining[size_t(team)] = player_count / team_count + (remainder > team ? 1 : 0);
	}

	int32_t assigned_count = 0;
	for (int32_t color = 0; color < 8; ++color) {
		if (group_members[size_t(color)] == 0U) {
			continue;
		}
		int32_t available_team_count = 0;
		for (int32_t team = 0; team < team_count; ++team) {
			if (remaining[size_t(team)] > 0) {
				available_team_count += 1;
			}
		}
		if (available_team_count <= 0) {
			return false;
		}
		int32_t selected_available_ordinal = rng.next() % available_team_count;
		int32_t selected_team = -1;
		for (int32_t team = 0; team < team_count; ++team) {
			if (remaining[size_t(team)] <= 0) {
				continue;
			}
			if (selected_available_ordinal == 0) {
				selected_team = team;
				break;
			}
			selected_available_ordinal -= 1;
		}
		if (selected_team < 0) {
			return false;
		}
		remaining[size_t(selected_team)] -= 1;
		assignments[size_t(color)] = uint8_t(first_team + selected_team);
		assigned_count += 1;
	}
	return assigned_count == player_count;
}

